// P12 (room layout) against the oracle on its scenarios:
//   ow-tour, ow-tour-west   overworld tours generated by tests/game/p12-make-movies.mjs (59 + 53 rooms)
//   cave-and-cellar         sword cave of $77, walk to level 1 and its first UW rooms
//   walk-first-screens      first OW scrolls
// Three checks per movie:
//  1. the oracle run reaches the scenario's states (*.expect.json) and Link never dies;
//  2. graft: the ORIGINAL game runs in jsnes with every P12 routine executed by the JS port
//     (tests/game/p12-graft.mjs; routines not yet ported in JS run as original code): RAM/SRAM diff 0;
//  3. full port (src/headless.js): diff 0, skipped while the port hits a NotImplementedError
//     (P05/P13 and later packages).
// Skipped without roms/zelda.nes or jsnes.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { readTrace } from '../../tools/oracle/lib/trace.mjs';
import { loadVarNames } from '../../tools/oracle/lib/var-names.mjs';
import { hasRom, ROOT } from '../core/helpers.mjs';
import { hasJsnes } from '../../tools/oracle/lib/jsnes-loader.mjs';

const ok = hasRom && (await hasJsnes());
const skip = !ok && 'needs roms/zelda.nes and tools/oracle jsnes';
const MOVIES = join(ROOT, 'tests/oracle/movies');
const SCENARIOS = ['walk-first-screens', 'cave-and-cellar', 'ow-tour', 'ow-tour-west'];

function node(args) {
  try {
    return { code: 0, out: execFileSync(process.execPath, args, { cwd: ROOT, encoding: 'utf8', stdio: 'pipe', maxBuffer: 1 << 26 }) };
  } catch (e) {
    return { code: e.status ?? 1, out: `${e.stdout ?? ''}${e.stderr ?? ''}` };
  }
}

for (const name of SCENARIOS) {
  test(`P12 ${name}: oracle expectations, graft and full port`, { skip, timeout: 1800000 }, async (t) => {
    const movie = join(MOVIES, `${name}.zmv`);
    if (!existsSync(movie)) {
      t.skip(`${name}.zmv not generated (node tests/game/p12-make-movies.mjs ${name})`);
      return;
    }
    const oracleDir = `out/p12/oracle/${name}`;
    await t.test('oracle', async () => {
      const r = node(['tools/oracle/run-oracle.mjs', movie, '--png', 'none', '--quiet', '--out', oracleDir]);
      assert.equal(r.code, 0, r.out);
      const frames = readTrace(join(ROOT, oracleDir, 'trace.ztrace')).frames;
      assert.ok(!frames.some((f) => f.ram[0x12] === 0x11), `${name}: Link dies (GameMode $11)`);
      const expectPath = join(MOVIES, `${name}.expect.json`);
      if (!existsSync(expectPath)) return;
      const expect = JSON.parse(readFileSync(expectPath, 'utf8'));
      const names = await loadVarNames();
      for (const [v, values] of Object.entries(expect.reaches ?? {})) {
        const addr = names.resolve(v);
        for (const value of [].concat(values)) {
          assert.ok(frames.some((f) => f.ram[addr] === value), `${name}: ${v} never reaches ${value}`);
        }
      }
    });
    await t.test('graft', () => {
      let r = node(['--import', './tests/game/p01-hybrid-register.mjs', 'tests/game/p12-graft.mjs', movie,
        '--out', `out/p12/graft/${name}`]);
      assert.equal(r.code, 0, r.out);
      t.diagnostic(`${name}: ${r.out.trim().split('\n').find((l) => l.startsWith('grafted')) ?? ''}`);
      r = node(['tools/oracle/diff.mjs', `${oracleDir}/trace.ztrace`, `out/p12/graft/${name}/trace.ztrace`, '--no-fb']);
      assert.equal(r.code, 0, r.out);
    });
    await t.test('full port', (st) => {
      const r = node(['tools/oracle/run-port.mjs', '--inputs-from', `${oracleDir}/trace.ztrace`, '--out', `out/p12/port/${name}`]);
      if (r.code !== 0 && /NotImplementedError|is not ported yet/.test(r.out)) {
        st.skip(`port incomplete: ${(r.out.match(/[^\n]*is not ported yet/) ?? ['NotImplementedError'])[0]}`);
        return;
      }
      assert.equal(r.code, 0, r.out);
      const d = node(['tools/oracle/diff.mjs', `${oracleDir}/trace.ztrace`, `out/p12/port/${name}/trace.ztrace`, '--no-fb']);
      assert.equal(d.code, 0, d.out);
    });
  });
}
